import sys
import numpy as np

def main():
    data = sys.stdin.read().split('\n')
    if not data or data[0].strip() == '':
        return
    try:
        n = int(data[0].strip())
    except ValueError:
        return

    records = []
    for i in range(1, n + 1):
        line = data[i] if i < len(data) else ''
        tokens = line.split()
        values = []
        for tok in tokens[1:]:
            try:
                values.append(float(tok))
            except ValueError:
                values.append(np.nan)
        records.append(values)

    if n == 0:
        return

    M = max((len(r) for r in records), default=0)
    if M == 0:
        return

    matrix = np.full((n, M), np.nan)
    for idx, r in enumerate(records):
        if r:
            matrix[idx, :len(r)] = r

    with np.errstate(invalid='ignore'):
        means = np.nanmean(matrix, axis=0)

    out_lines = []
    for p in range(M):
        val = means[p]
        if np.isnan(val):
            out_lines.append(f"Position {p+1}: nan")
        else:
            fval = float(val)
            out_lines.append(f"Position {p+1}: {fval}")

    print('\n'.join(out_lines))

if __name__ == '__main__':
    main()

