import sys
import json
from collections import OrderedDict
from dateutil import parser as dateparser

class UnsupportedType(Exception):
    pass

def resolve(obj):
    if isinstance(obj, dict):
        if set(obj.keys()) == {"__type__", "__value__"}:
            t = obj["__type__"]
            v = obj["__value__"]
            if t == "datetime":
                # validate but return unchanged
                dateparser.isoparse(v) if isinstance(v, str) else None
                return resolve(v)
            elif t == "ndarray":
                return resolve(v)
            elif t == "decimal":
                return resolve(v)
            else:
                raise UnsupportedType()
        if "__type__" in obj:
            tv = obj["__type__"]
            if tv not in ("datetime", "ndarray", "decimal"):
                raise UnsupportedType()
        new = OrderedDict()
        for k, val in obj.items():
            new[k] = resolve(val)
        return new
    elif isinstance(obj, list):
        return [resolve(x) for x in obj]
    else:
        return obj

def main():
    data = sys.stdin.read()
    doc = json.loads(data, object_pairs_hook=OrderedDict)
    try:
        result = resolve(doc)
    except UnsupportedType:
        sys.stdout.write("TypeError: unsupported type")
        return
    sys.stdout.write(json.dumps(result, separators=(", ", ": "), ensure_ascii=False))

if __name__ == "__main__":
    main()

