        sums = []
    else:
        combos = itertools.combinations(elements, k)
        sums = [sum(c) for c in combos]

    if sums:
        arr = np.array(sums, dtype=object)
        product = np.prod(arr)
    else:
        product = 1

    top = sorted(sums, reverse=True)[:top_n] if sums else []

    out_lines = [str(product)]
    for s in top:
        out_lines.append(str(s))

    sys.stdout.write('\n'.join(out_lines) + ('\n' if out_lines else ''))

