def main():
    data_input = sys.stdin.read().splitlines()
    if not data_input:
        return
    first_line = data_input[0].split(',')
    R = int(first_line[0].strip())
    C = int(first_line[1].strip())

    if len(data_input) > 1:
        cols = data_input[1].split(',') if data_input[1] != '' else []
    else:
        cols = []

    # Ensure we have exactly C column names (pad if necessary)
    if C > 0:
        if len(cols) < C:
            cols = cols + [''] * (C - len(cols))
        elif len(cols) > C:
            cols = cols[:C]
    else:
        cols = []

    rows = []
    for i in range(R):
        line_idx = 2 + i
        if line_idx < len(data_input):
            row = data_input[line_idx].split(',')
        else:
            row = []
        if C > 0:
            if len(row) < C:
                row = row + [''] * (C - len(row))
            elif len(row) > C:
                row = row[:C]
        else:
            row = []
        rows.append(row)

    # Print header
    print(','.join(cols))

    if C == 0:
        for _ in range(R):
            print('')
