def main():
    data = sys.stdin.read().split('\n')
    idx = 0
    first_line = data[idx].split()
    idx += 1
    n = int(first_line[0])
    m = int(first_line[1])
    col_names = data[idx].split()
    idx += 1
    raw_points = []
    coords = []
    for i in range(n):
        line = data[idx]
        idx += 1
        tokens = line.split()
        raw_points.append(tokens)
        coords.append([float(t) for t in tokens])

    eps = 3.0
    min_samples = 2

    def dist(a, b):
        s = 0.0
        for k in range(m):
            d = coords[a][k] - coords[b][k]
            s += d * d
        return math.sqrt(s)

    # determine core points
    core = [False] * n
    for i in range(n):
        cnt = 0
        for j in range(n):
            if dist(i, j) <= eps:
                cnt += 1
        if cnt >= min_samples:
            core[i] = True

    core_indices = [i for i in range(n) if core[i]]
    core_set = set(core_indices)

    label_map = {}
    cluster_id = 0

    for i in range(n):
        if i in core_set and i not in label_map:
            stack = [i]
            while stack:
                cur = stack.pop()
                if cur in label_map:
                    continue
                label_map[cur] = cluster_id
                for j in core_indices:
                    if j != cur and j not in label_map and dist(cur, j) <= eps:
                        stack.append(j)
            cluster_id += 1

    labels = [-1] * n
    for i in core_indices:
        labels[i] = label_map[i]

    for p in range(n):
        if p in core_set:
            continue
        assigned = -1
        for c in core_indices:
            if dist(p, c) <= eps:
                assigned = label_map[c]
                break
        labels[p] = assigned

    out_lines = []
    header = ",".join(col_names + ["Cluster"])
    out_lines.append(header)
    for i in range(n):
        row = ",".join(raw_points[i] + [str(labels[i])])
        out_lines.append(row)

