def main():
    data = sys.stdin.read().splitlines()
    if not data:
        return
    try:
        n = int(data[0].strip())
    except ValueError:
        n = 0
    docs = []
    for i in range(1, n+1):
        if i < len(data):
            docs.append(data[i])
        else:
            docs.append('')
    url_pattern = re.compile(r'https?://\S+')
    word_pattern = re.compile(r'[A-Za-z0-9_]{2,}')
    cleaned_docs = []
    for doc in docs:
        no_url = url_pattern.sub('', doc)
        words = [w.lower() for w in word_pattern.findall(no_url)]
        cleaned_docs.append(words)
    vocab_set = set()
    for words in cleaned_docs:
        vocab_set.update(words)
    vocab = sorted(vocab_set)
    if not vocab:
        return
    vocab_index = {w: i for i, w in enumerate(vocab)}
    V = len(vocab)
    tf = [[0]*V for _ in range(n)]
    for i, words in enumerate(cleaned_docs):
        for w in words:
            tf[i][vocab_index[w]] += 1
    df = [0]*V
    for j in range(V):
        cnt = 0
        for i in range(n):
            if tf[i][j] > 0:
                cnt += 1
        df[j] = cnt
    idf = [math.log((1+n)/(1+df[j])) + 1 for j in range(V)]
    raw = [[tf[i][j]*idf[j] for j in range(V)] for i in range(n)]
    out_lines = [' '.join(vocab)]
    for i in range(n):
        norm = math.sqrt(sum(x*x for x in raw[i]))
        if norm == 0:
            vec = [0.0]*V
        else:
            vec = [x/norm for x in raw[i]]
        rounded = [round(x, 8) for x in vec]
        out_lines.append(' '.join(str(x) for x in rounded))
    sys.stdout.write('\n'.join(out_lines) + '\n')

