import sys, math

def haversine(lat1, lon1, lat2, lon2):
    R = 6371.0
    phi1 = math.radians(lat1)
    phi2 = math.radians(lat2)
    dphi = math.radians(lat2 - lat1)
    dlambda = math.radians(lon2 - lon1)
    a = math.sin(dphi/2)**2 + math.cos(phi1)*math.cos(phi2)*math.sin(dlambda/2)**2
    a = min(1.0, max(0.0, a))
    c = 2 * math.asin(math.sqrt(a))
    return R * c

def main():
    data = sys.stdin.read().splitlines()
    idx = 0
    if idx >= len(data):
        return
    try:
        n = int(data[idx].strip())
    except Exception:
        # malformed n line - treat as no data
        n = 0
    idx += 1

    points = []
    for i in range(n):
        if idx >= len(data):
            line = ""
        else:
            line = data[idx]
        idx += 1
        parts = line.split()
        if len(parts) >= 2:
            lat = float(parts[0])
            lon = float(parts[1])
        else:
            lat = 0.0
            lon = 0.0
        points.append((lat, lon, line.strip()))

    if idx >= len(data):
        target_line = ""
    else:
        target_line = data[idx]
    idx += 1

    tparts = target_line.split()
    if len(tparts) >= 2:
        tlat = float(tparts[0])
        tlon = float(tparts[1])
    else:
        tlat = 0.0
        tlon = 0.0

    if idx >= len(data):
        k_token = ""
    else:
        k_token = data[idx].strip()
    idx += 1

    try:
        k = int(k_token)
        if k < 0:
            raise ValueError
    except Exception:
        print("ValueError")
        return

    dists = []
    for i, p in enumerate(points):
        d = haversine(tlat, tlon, p[0], p[1])
        dists.append((d, i, p))

