import sys
from datetime import datetime
from dateutil import parser as dtparser

def main():
    data = sys.stdin.read().splitlines()
    idx = 0
    if idx >= len(data):
        return
    header = data[idx].split(',')
    idx += 1

    rows = []
    while idx < len(data) and data[idx] != 'END':
        rows.append(data[idx].split(','))
        idx += 1
    # skip the END line
    if idx < len(data) and data[idx] == 'END':
        idx += 1

    if idx >= len(data):
        col_name = ''
    else:
        col_name = data[idx].strip()
        idx += 1

    start_str = data[idx].strip() if idx < len(data) else ''
    idx += 1
    end_str = data[idx].strip() if idx < len(data) else ''
    idx += 1

    if col_name not in header:
        print('Error: column not found')
        return

    col_idx = header.index(col_name)

    def parse_strict_date(s):
        return datetime.strptime(s, '%Y-%m-%d').date()

    try:
        start_date = parse_strict_date(start_str)
        end_date = parse_strict_date(end_str)
    except (ValueError, TypeError):
        print('Error: invalid date format')
        return

    parsed_dates = []
    try:
        for row in rows:
            val = row[col_idx].strip() if col_idx < len(row) else ''
            d = dtparser.parse(val).date()
            parsed_dates.append(d)
    except (ValueError, OverflowError, TypeError):
        print('Error: invalid date format')
        return

    result_rows = []
    for row, d in zip(rows, parsed_dates):
        if start_date <= d <= end_date:
            result_rows.append(row)

    output_lines = [','.join(header)]
    for row in result_rows:
        output_lines.append(','.join(row))

    print('\n'.join(output_lines))

if __name__ == '__main__':
    main()
